import React, { useEffect, useState, useRef } from 'react';
import {
  View,
  Text,
  StyleSheet,
  FlatList,
  TextInput,
  TouchableOpacity,
  Alert,
  ActivityIndicator,
  Platform,
  KeyboardAvoidingView,
  Animated,
  Image,
  Easing,
} from 'react-native';
import { useNavigation } from '@react-navigation/native';
import {
  collection,
  onSnapshot,
  query,
  orderBy,
  deleteDoc,
  doc,
  addDoc,
  updateDoc,
  arrayUnion,
  getDoc,
} from 'firebase/firestore';
import { firestore, auth } from '../services/firebaseConfig';
import { confirmAction } from '../utils/confirmAction';

const UIDS_PERMITIDOS = [
  'qAvyxYtraUPmd06d3jufwqPi7vo2',
  'g8KmZsmMqfPEqAM3NWF7qs33Gid2',
  'bVpx7GAuLuTbRVWfPOT57vgO9cL2',
];

interface Aviso {
  id?: string;
  titulo: string;
  mensagem: string;
  criadoEm: any;
  visualizadosPor?: string[];
  curtidas?: string[];
}

interface UsuarioInfo {
  nome?: string;
  email?: string;
}

const NeumorphicContainer = ({ children, style }: any) => (
  <View style={[styles.neumorphicOuter, style]}>
    <View style={styles.neumorphicInner}>{children}</View>
  </View>
);

function JoinhaIcon({ color = '#bbb', size = 30 }: { color?: string; size?: number }) {
  return (
    <Text style={{ fontSize: size, color }}>{'\u{1F44D}'}</Text>
  );
}

export default function AvisosScreen() {
  const navigation = useNavigation();
  const [avisos, setAvisos] = useState<Aviso[]>([]);
  const [uidAtual, setUidAtual] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [novoTitulo, setNovoTitulo] = useState('');
  const [novoMensagem, setNovoMensagem] = useState('');
  const [mostrarCamposNovo, setMostrarCamposNovo] = useState(false);
  const [editandoId, setEditandoId] = useState<string | null>(null);
  const [editTitulo, setEditTitulo] = useState('');
  const [editMensagem, setEditMensagem] = useState('');
  const [usuariosInfo, setUsuariosInfo] = useState<{ [uid: string]: UsuarioInfo }>({});

  const animatedValues = useRef<Animated.Value[]>([]);
  const likeScales = useRef<{ [id: string]: Animated.Value }>({}).current;
  const likeBounces = useRef<{ [id: string]: Animated.Value }>({}).current;
  const likePulse = useRef<{ [id: string]: Animated.Value }>({}).current;
  const likeRing = useRef<{ [id: string]: Animated.Value }>({}).current;

  async function buscarNomesCurtidores(uids: string[]) {
    const novos: { [uid: string]: UsuarioInfo } = { ...usuariosInfo };
    for (const uid of uids) {
      if (!novos[uid]) {
        try {
          const snap = await getDoc(doc(firestore, 'usuarios', uid));
          if (snap.exists()) {
            novos[uid] = {
              nome: snap.data().nome || undefined,
              email: snap.data().email || undefined,
            };
          } else {
            novos[uid] = { nome: undefined, email: undefined };
          }
        } catch {
          novos[uid] = { nome: undefined, email: undefined };
        }
      }
    }
    setUsuariosInfo(novos);
  }

  const permitido = !!uidAtual && UIDS_PERMITIDOS.includes(uidAtual);

  useEffect(() => {
    const uid = auth.currentUser?.uid ?? null;
    setUidAtual(uid);

    const avisosQuery = query(
      collection(firestore, 'avisos'),
      orderBy('criadoEm', 'desc')
    );

    const unsubscribe = onSnapshot(avisosQuery, async (querySnapshot) => {
      const data = querySnapshot.docs.map(docSnap => ({
        id: docSnap.id,
        ...docSnap.data(),
      }));

      if (uid) {
        await Promise.all(querySnapshot.docs.map(async docSnap => {
          const aviso = docSnap.data() as Aviso;
          if (!aviso.visualizadosPor || !aviso.visualizadosPor.includes(uid)) {
            await updateDoc(doc(firestore, 'avisos', docSnap.id), {
              visualizadosPor: arrayUnion(uid),
            });
          }
        }));
      }

      setAvisos(data as Aviso[]);
      setLoading(false);

      const allUids: string[] = [];
      data.forEach((aviso: Aviso) => {
        if (aviso.curtidas) {
          aviso.curtidas.forEach(uid => {
            if (!allUids.includes(uid)) allUids.push(uid);
          });
        }
      });
      if (allUids.length > 0) await buscarNomesCurtidores(allUids);
    }, (error) => {
      console.log('Erro ao buscar avisos:', error);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  useEffect(() => {
    animatedValues.current = avisos.map(() => new Animated.Value(30));
    Animated.stagger(80, animatedValues.current.map(anim =>
      Animated.timing(anim, {
        toValue: 0,
        duration: 400,
        useNativeDriver: true,
      })
    )).start();
  }, [avisos.length]);

  useEffect(() => {
    avisos.forEach(aviso => {
      if (!aviso.id) return;

      if (!likePulse[aviso.id]) {
        likePulse[aviso.id] = new Animated.Value(1);
      }
      if (!likeRing[aviso.id]) {
        likeRing[aviso.id] = new Animated.Value(0);
      }

      // Só anima o joinha se o usuário NÃO curtiu
      const curtidas = aviso.curtidas || [];
      const usuarioCurtiu = curtidas.includes(uidAtual || '');

      if (!usuarioCurtiu) {
        Animated.loop(
          Animated.sequence([
            Animated.timing(likePulse[aviso.id], {
              toValue: 1.25,
              duration: 600,
              easing: Easing.inOut(Easing.ease),
              useNativeDriver: true,
            }),
            Animated.timing(likePulse[aviso.id], {
              toValue: 1,
              duration: 600,
              easing: Easing.inOut(Easing.ease),
              useNativeDriver: true,
            }),
          ])
        ).start();

        Animated.loop(
          Animated.sequence([
            Animated.timing(likeRing[aviso.id], {
              toValue: 1,
              duration: 1200,
              easing: Easing.out(Easing.ease),
              useNativeDriver: true,
            }),
            Animated.timing(likeRing[aviso.id], {
              toValue: 0,
              duration: 0,
              useNativeDriver: true,
            }),
          ])
        ).start();
      } else {
        // Para animação se curtiu
        likePulse[aviso.id].setValue(1);
        likeRing[aviso.id].setValue(0);
      }
    });
    // eslint-disable-next-line
  }, [avisos.map(a => a.id + (a.curtidas || []).join(',')).join(',')]);

  const excluirAviso = async (id: string) => {
    if (!uidAtual || !UIDS_PERMITIDOS.includes(uidAtual)) return;
    confirmAction({
      title: 'Excluir aviso',
      message: 'Tem certeza que deseja excluir este aviso?',
      onConfirm: async () => {
        try {
          await auth.currentUser?.getIdToken(true);
          await deleteDoc(doc(firestore, 'avisos', id));
          setAvisos(prev => prev.filter(aviso => aviso.id !== id));
        } catch (error: any) {
          console.log('Erro ao excluir aviso:', error);
        }
      },
    });
  };

  const handleCriarAviso = async () => {
    if (!novoTitulo.trim() || !novoMensagem.trim()) {
      Alert.alert('Atenção', 'Preencha o título e a mensagem.');
      return;
    }
    try {
      await addDoc(collection(firestore, 'avisos'), {
        titulo: novoTitulo,
        mensagem: novoMensagem,
        criadoEm: new Date(),
        visualizadosPor: [],
        curtidas: [],
      });
      setNovoTitulo('');
      setNovoMensagem('');
      setMostrarCamposNovo(false);
    } catch {
      Alert.alert('Erro', 'Não foi possível criar o aviso.');
    }
  };

  const handleEditarAviso = (aviso: Aviso) => {
    setEditandoId(aviso.id!);
    setEditTitulo(aviso.titulo);
    setEditMensagem(aviso.mensagem);
  };

  const handleSalvarEdicao = async () => {
    if (!editTitulo.trim() || !editMensagem.trim() || !editandoId) {
      Alert.alert('Atenção', 'Preencha o título e a mensagem.');
      return;
    }
    try {
      await updateDoc(doc(firestore, 'avisos', editandoId), {
        titulo: editTitulo,
        mensagem: editMensagem,
      });
      setEditandoId(null);
      setEditTitulo('');
      setEditMensagem('');
    } catch {
      Alert.alert('Erro', 'Não foi possível salvar o aviso.');
    }
  };

  const handleCurtirAviso = async (aviso: Aviso) => {
    if (!uidAtual || !aviso.id) return;
    const avisoDoc = doc(firestore, 'avisos', aviso.id);
    const docSnap = await getDoc(avisoDoc);
    let curtidasArr: string[] = [];
    if (docSnap.exists()) {
      curtidasArr = docSnap.data().curtidas || [];
    }
    if (curtidasArr.includes(uidAtual)) {
      curtidasArr = curtidasArr.filter(uid => uid !== uidAtual);
    } else {
      curtidasArr.push(uidAtual);
    }
    await updateDoc(avisoDoc, { curtidas: curtidasArr });

    if (!likeScales[aviso.id!]) {
      likeScales[aviso.id!] = new Animated.Value(1);
    }
    Animated.sequence([
      Animated.timing(likeScales[aviso.id!], { toValue: 1.3, duration: 120, useNativeDriver: true }),
      Animated.timing(likeScales[aviso.id!], { toValue: 1, duration: 120, useNativeDriver: true }),
    ]).start();

    if (!likeBounces[aviso.id!]) {
      likeBounces[aviso.id!] = new Animated.Value(0);
    }
    likeBounces[aviso.id!].setValue(0);
    Animated.sequence([
      Animated.timing(likeBounces[aviso.id!], {
        toValue: -18,
        duration: 120,
        easing: Easing.out(Easing.quad),
        useNativeDriver: true,
      }),
      Animated.timing(likeBounces[aviso.id!], {
        toValue: 0,
        duration: 180,
        easing: Easing.bounce,
        useNativeDriver: true,
      }),
    ]).start();
  };

  const renderItem = ({ item, index }: { item: Aviso; index: number }) => {
    if (!item.id) return null;
    const curtidas = item.curtidas || [];
    const isAdmin = permitido;
    const usuarioCurtiu = curtidas.includes(uidAtual || '');

    const nomesCurtidores: string[] = curtidas.map(uid => usuariosInfo[uid]?.nome ?? '');
    const nomesEmDuplas: string[][] = [];
    for (let i = 0; i < nomesCurtidores.length; i += 2) {
      nomesEmDuplas.push(nomesCurtidores.slice(i, i + 2));
    }

    if (!likeScales[item.id]) {
      likeScales[item.id] = new Animated.Value(1);
    }
    if (!likeBounces[item.id]) {
      likeBounces[item.id] = new Animated.Value(0);
    }
    if (!likePulse[item.id]) {
      likePulse[item.id] = new Animated.Value(1);
    }
    if (!likeRing[item.id]) {
      likeRing[item.id] = new Animated.Value(0);
    }

    const ringScale = likeRing[item.id].interpolate({
      inputRange: [0, 1],
      outputRange: [1, 2.4],
    });
    const ringOpacity = likeRing[item.id].interpolate({
      inputRange: [0, 0.7, 1],
      outputRange: [0.5, 0.25, 0],
    });

    // Joinha animado até clicar, depois cor amarela e sem animação
    const joinhaColor = usuarioCurtiu ? '#ffe066' : '#bbb';
    const joinhaAnimatedStyle = usuarioCurtiu
      ? { transform: [{ scale: likeScales[item.id] }, { translateY: likeBounces[item.id] }] }
      : { transform: [{ scale: likePulse[item.id] }, { translateY: likeBounces[item.id] }] };

    return (
      <Animated.View style={{
        transform: [{ translateY: animatedValues.current[index] || new Animated.Value(0) }],
        opacity: animatedValues.current[index]
          ? animatedValues.current[index].interpolate({ inputRange: [0, 30], outputRange: [1, 0.7] })
          : 1,
        marginBottom: 18,
      }}>
        <NeumorphicContainer style={styles.avisoBox}>
          {editandoId === item.id && isAdmin ? (
            <>
              <TextInput
                style={styles.input}
                value={editTitulo}
                onChangeText={setEditTitulo}
                placeholder="Título"
                placeholderTextColor="#aaa"
              />
              <TextInput
                style={[styles.input, { minHeight: 60 }]}
                value={editMensagem}
                onChangeText={setEditMensagem}
                multiline
                placeholder="Mensagem"
                placeholderTextColor="#aaa"
              />
              <View style={styles.row}>
                <TouchableOpacity style={[styles.botao, styles.botaoSalvar]} onPress={handleSalvarEdicao}>
                  <Text style={[styles.botaoTexto, { color: '#fff' }]}>Salvar</Text>
                </TouchableOpacity>
                <TouchableOpacity style={[styles.botao, styles.botaoCancelar]} onPress={() => setEditandoId(null)}>
                  <Text style={[styles.botaoTexto, { color: '#fff' }]}>Cancelar</Text>
                </TouchableOpacity>
              </View>
            </>
          ) : (
            <>
              <Text style={styles.avisoTitulo}>{item.titulo}</Text>
              <Text style={styles.avisoMensagem}>{item.mensagem}</Text>
              <Text style={styles.avisoData}>
                {item.criadoEm?.toDate ? item.criadoEm.toDate().toLocaleString() : ''}
              </Text>
              <View style={styles.curtidasRow}>
                <View style={{ position: 'relative', alignItems: 'center', justifyContent: 'center' }}>
                  {!usuarioCurtiu && (
                    <Animated.View
                      pointerEvents="none"
                      style={{
                        position: 'absolute',
                        width: 44,
                        height: 44,
                        borderRadius: 22,
                        borderWidth: 3,
                        borderColor: '#ffe066',
                        opacity: ringOpacity,
                        transform: [{ scale: ringScale }],
                        zIndex: 0,
                      }}
                    />
                  )}
                  <Animated.View
                    style={{
                      ...joinhaAnimatedStyle,
                      zIndex: 1,
                    }}
                  >
                    <TouchableOpacity
                      onPress={() => handleCurtirAviso(item)}
                      style={styles.curtidaBtn}
                      activeOpacity={0.7}
                    >
                      <JoinhaIcon color={joinhaColor} size={30} />
                    </TouchableOpacity>
                  </Animated.View>
                </View>
                {isAdmin ? (
                  <>
                    <Text style={{ fontSize: 13, color: '#ff9800', fontWeight: 'bold', marginRight: 4 }}>
                      Curtiram:
                    </Text>
                    {curtidas.length > 0 && (
                      <View style={{ flexDirection: 'column', marginLeft: 2, marginTop: 6 }}>
                        {nomesEmDuplas.map((dupla, idx) => (
                          <View key={idx} style={{ flexDirection: 'row', marginBottom: 3 }}>
                            {dupla.map((nome, i) => (
                              <Text
                                key={i}
                                style={{
                                  fontSize: 13,
                                  color: '#ff9800',
                                  backgroundColor: '#23243a',
                                  borderRadius: 8,
                                  paddingHorizontal: 10,
                                  paddingVertical: 4,
                                  marginRight: 6,
                                  marginBottom: 2,
                                  minWidth: 60,
                                  textAlign: 'center',
                                }}
                              >
                                {nome}
                              </Text>
                            ))}
                          </View>
                        ))}
                      </View>
                    )}
                  </>
                ) : (
                  <Text style={{ fontSize: 14, color: '#ff9800', fontWeight: 'bold', marginLeft: 2 }}>
                    {curtidas.length}
                  </Text>
                )}
              </View>
              {isAdmin && (
                <View style={styles.botoesRow}>
                  <TouchableOpacity
                    style={[styles.botao, styles.botaoEditar, styles.botaoEditarShadow]}
                    onPress={() => handleEditarAviso(item)}
                    activeOpacity={0.8}
                  >
                    <Text style={styles.botaoTextoEditar}>✏️ Editar</Text>
                  </TouchableOpacity>
                  <TouchableOpacity
                    style={[styles.botao, styles.botaoExcluir, styles.botaoExcluirShadow]}
                    onPress={() => excluirAviso(item.id!)}
                    activeOpacity={0.8}
                  >
                    <Text style={styles.botaoTextoExcluir}>🗑 Excluir</Text>
                  </TouchableOpacity>
                </View>
              )}
            </>
          )}
        </NeumorphicContainer>
      </Animated.View>
    );
  };

  return (
    <View style={styles.bg}>
      <KeyboardAvoidingView
        style={{ flex: 1 }}
        behavior={Platform.OS === 'ios' ? 'padding' : undefined}
      >
        <View style={styles.container}>
          <NeumorphicContainer style={styles.header}>
            <View style={styles.headerRow}>
              <TouchableOpacity style={styles.headerBtn} onPress={() => navigation.navigate('Inicio')}>
				<Image
				  source={{ uri: 'https://img.icons8.com/?size=100&id=bIwuxbfp2H2N&format=png&color=000000.png' }}
				  style={styles.headerIcon}
				/>
			  </TouchableOpacity>
              <Text style={styles.headerTitle}>🔔Painel de Avisos</Text>
              <TouchableOpacity style={styles.headerBtn} onPress={() => navigation.goBack()}>
				<Image
				  source={{ uri: 'https://img.icons8.com/?size=100&id=CFDbApIER33U&format=png&color=000000.png' }}
				  style={styles.headerIcon}
				/>
			  </TouchableOpacity>
            </View>
          </NeumorphicContainer>

          {permitido && (
            mostrarCamposNovo ? (
              <NeumorphicContainer style={styles.novoAvisoBox}>
                <Text style={styles.novoAvisoTitulo}>Novo aviso</Text>
                <TextInput
                  style={styles.input}
                  placeholder="Título do aviso"
                  value={novoTitulo}
                  onChangeText={setNovoTitulo}
                  placeholderTextColor="#aaa"
                />
                <TextInput
                  style={[styles.input, { minHeight: 60 }]}
                  placeholder="Digite sua mensagem"
                  value={novoMensagem}
                  onChangeText={setNovoMensagem}
                  multiline
                  placeholderTextColor="#aaa"
                />
                <TouchableOpacity style={[styles.botao, styles.botaoCriar]} onPress={handleCriarAviso}>
                  <Text style={styles.botaoTexto}>Criar Aviso</Text>
                </TouchableOpacity>
              </NeumorphicContainer>
            ) : (
              <NeumorphicContainer style={{ marginBottom: 18, alignSelf: 'center', minWidth: 160 }}>
                <TouchableOpacity
                  style={[styles.botao, styles.botaoCriar, { backgroundColor: 'transparent', elevation: 0 }]}
                  onPress={() => setMostrarCamposNovo(true)}
                >
                  <Text style={styles.botaoTexto}>Criar novo aviso</Text>
                </TouchableOpacity>
              </NeumorphicContainer>
            )
          )}

          {loading ? (
            <ActivityIndicator size="large" color="#ff9800" style={{ marginTop: 30 }} />
          ) : (
            <FlatList
              data={avisos}
              keyExtractor={item => item.id!}
              renderItem={renderItem}
              extraData={usuariosInfo}
              ListEmptyComponent={
                <Text style={{ color: '#888', marginTop: 30, textAlign: 'center' }}>Nenhum aviso cadastrado.</Text>
              }
              contentContainerStyle={{ paddingBottom: 30 }}
              showsVerticalScrollIndicator={false}
            />
          )}
        </View>
      </KeyboardAvoidingView>
    </View>
  );
}

